;// ./src/editor/src/utils/compilation/build/cleanup.ts

async function clearFolders({ projectPath, outputPath, files }) {
    const topLevelFolders = [];
    // Collect toplevel folders
    for (const i in files) {
        const file = files[i];
        const localPath = file.fullPath.substring(projectPath.length + 1);
        // File is in a subfolder of the project directory, delete it
        // but make sure to never delete .git
        if (localPath.indexOf('/') !== -1 && localPath.substring(0, 4) !== '.git') {
            const comps = localPath.split('/');
            const topFolderName = comps[0];
            if (topLevelFolders.indexOf(topFolderName) === -1) {
                topLevelFolders.push(topFolderName);
            }
        }
    }
    // No folders to clear
    if (topLevelFolders.length === 0) {
        return;
    }
    let foldersToClear = topLevelFolders.length;
    for (const i in topLevelFolders) {
        const t = topLevelFolders[i];
        await src.filesystem.removeDirRecursive(outputPath + '/' + t);
        foldersToClear--;
        if (foldersToClear === 0)
            return;
    }
}

;// ./src/editor/src/utils/compilation/build/copy.ts


async function copyProjectFilesToFolder(projectPath, direntry) {
    // TODO: Load something like .noodlignore file list
    const ignoreFiles = ['.DS_Store', '.gitignore', '.gitattributes', 'project.json', 'Dockerfile'];
    // Copy everything from the project folder
    if (!projectPath) {
        throw new Error('Couldnt open project folder.');
    }
    await src.filesystem.makeDirectory(direntry);
    let files = await src.filesystem.listDirectoryFiles(projectPath);
    files = files.filter((f) => {
        if (ignoreFiles.indexOf(f.name) !== -1)
            return false;
        // TODO: Make this easier to access
        if (f.fullPath.indexOf('.git') !== -1)
            return false; // Ignore git files
        if (f.fullPath.indexOf('.noodl') !== -1)
            return false; // Ignore noodl files
        return true;
    });
    // First clear all folders, will be recreated later
    await clearFolders({
        projectPath,
        outputPath: direntry,
        files
    });
    let filesLeftToCopy = 0;
    let totalSuccess = true;
    function fileCompleted(success) {
        filesLeftToCopy--;
        totalSuccess = totalSuccess && success;
    }
    async function makeDirectoryAndCopyFile(f) {
        // TODO: This requires that the project path is looking nice
        // Example:
        // C:\\Users\\Eric\\AppData\\Roaming\\Noodl\\projects\\9acdd495-3d92-4490-ae0a-44f17bf47dca
        // C:\Users\Eric\AppData\Roaming\Noodl\projects\9acdd495-3d92-4490-ae0a-44f17bf47dca\noodl_modules\
        //                                                                       it will cut here ^
        const folderPath = f.fullPath.substring(projectPath.length, f.fullPath.length - f.name.length - 1);
        const localPath = f.fullPath.substring(projectPath.length);
        filesLeftToCopy++;
        const targetDir = src.filesystem.join(direntry, folderPath);
        await src.filesystem.makeDirectory(targetDir);
        try {
            await src.filesystem.copyFile(f.fullPath, direntry + '/' + localPath);
            fileCompleted(true);
        }
        catch (error) {
            console.error(error);
            fileCompleted(false);
        }
    }
    const tasks = files.map(makeDirectoryAndCopyFile);
    await Promise.all(tasks);
    if (!totalSuccess) {
        throw new Error('Failed to copy project files.');
    }
}

