function resetComponent(baseProjectJson, componentName) {
    const activityId = 'resetting-component';
    ToastLayer.ToastLayer.showActivity('Resetting component', activityId);
    //get previous version of component
    const baseCompJson = baseProjectJson.components.find((c) => c.name === componentName);
    const currentComponent = projectmodel.ProjectModel.instance.getComponentWithName(componentName);
    if (currentComponent && baseCompJson) {
        const isReplacingRootComponent = projectmodel.ProjectModel.instance.getRootComponent() === currentComponent;
        //we're resetting to a previous version of the same component
        //Do this by just replacing the graph, so we don't trigger ComponentRemoved and other events
        //that might affect Page Routers and have other unwanted side effects
        const graph = nodegraphmodel/* NodeGraphModel */.W2.fromJSON(baseCompJson.graph);
        currentComponent.bindGraph(graph);
        currentComponent.graph.evaluateHealth(); //update warnings
        if (isReplacingRootComponent) {
            //previous version of the component might have a different root node
            projectmodel.ProjectModel.instance.setRootComponent(currentComponent);
        }
        //reload viewers so they get a new export
        EventDispatcher.EventDispatcher.instance.emit('viewer-refresh');
    }
    else if (currentComponent) {
        //there is no old version, so this is a new component, delete it
        projectmodel.ProjectModel.instance.removeComponent(currentComponent);
    }
    else if (baseCompJson) {
        //the current version has been deleted, so add it back
        projectmodel.ProjectModel.instance.addComponent(componentmodel/* ComponentModel */.j.fromJSON(baseCompJson));
    }
    ToastLayer.ToastLayer.hideActivity(activityId);
    ToastLayer.ToastLayer.showSuccess('Component reset');
}
