async function whatsnewRender() {
    const newEditorVersionAvailable = JSON.parse(localStorage.getItem(LocalStorageKey.hasNewEditorVersionAvailable));
    // if user runs an older version the changelog will be irrelevant
    if (newEditorVersionAvailable)
        return;
    const latestChangelogPost = await fetch(`${(0,editor_getDocsEndpoint/* default */.A)()}/whats-new/feed.json`)
        .then((data) => data.json())
        .then((json) => json.items[0]);
    const lastSeenChangelogDate = new Date(JSON.parse(localStorage.getItem(LocalStorageKey.lastSeenChangelogDate))).getTime();
    const latestChangelogDate = new Date(latestChangelogPost.date_modified).getTime();
    if (lastSeenChangelogDate >= latestChangelogDate)
        return;
    external_electron_.ipcRenderer.send('viewer-hide');
    const modalContainer = document.createElement('div');
    modalContainer.classList.add('popup-layer-react-modal');
    popuplayer_default().instance.el.find('.popup-layer-modal').before(modalContainer);
    // Create root once and properly unmount when finished
    const modalRoot = (0,client.createRoot)(modalContainer);
    modalRoot.render(external_react_default().createElement(NewsModal, {
        content: latestChangelogPost.content_html,
        onFinished: () => {
            external_electron_.ipcRenderer.send('viewer-show');
            // Properly cleanup React root and DOM element
            modalRoot.unmount();
            modalContainer.remove();
        }
    }));
    localStorage.setItem(LocalStorageKey.lastSeenChangelogDate, latestChangelogDate.toString());
}

